        assertApiStatus(() -> service.createTask("INC-I1", "alice",
                new TaskCreateRequest(createKey, "T-2", "G", "t", List.of())),
                HttpStatus.CONFLICT);
        assertApiStatus(() -> service.completeTask("INC-I1", "T-1", "alice",
                new TaskActionRequest(createKey)), HttpStatus.CONFLICT);
