                new TaskActionRequest(completeKey));
        TaskView doneReplay = service.completeTask("INC-I1", "T-1", "alice",
                new TaskActionRequest(completeKey));
        assertThat(doneReplay).isEqualTo(done);
        assertThat(service.getTask("INC-I1", "T-1").status()).isEqualTo("DONE");
    }

