package com.example.starter.incident.plan;

import java.time.Instant;

/**
 * 方案版本行。versionNo 事件内递增；baseVersionId 仅 DRAFT 有值（其基版本）；
 * branch 为草稿分支标记（LEFT/RIGHT，仅信息性）；revision 为草稿修订计数器，
 * 每次草稿编辑 +1，合并请求以 expectedVersion 对齐；mergeKey 仅合并产生的版本有值。
 * 所有时间字段均为 UTC。
 */
public record PlanVersion(long id, long incidentId, int versionNo, PlanVersionStatus status,
                          Long baseVersionId, String branch, int revision, String mergeKey,
                          String createdBy, Instant createdAt, Instant publishedAt) {
}

package com.example.starter.incident.plan;

import java.time.Instant;

/**
 * 方案版本内的计划任务行。taskId 为跨版本稳定标识（三方合并按它对齐）；
 * 执行状态不落本表（见 plan_task_state），版本行发布后不可变。
 */
public record PlanTask(long id, long versionId, String taskId, String groupCode, String title,
                       String assignee, Instant createdAt) {

    /**
     * 计划字段内容比对（三方合并用）：groupCode/title/assignee 全同视为未修改。
     */
    public boolean sameContent(PlanTask other) {
        return other != null && groupCode.equals(other.groupCode)
                && title.equals(other.title) && assignee.equals(other.assignee);
    }
}

package com.example.starter.incident.plan;

import java.time.Instant;

/**
 * 方案版本内的依赖边：fromTaskId 为前置任务（本版本内 taskId）；
 * toIncidentKey 为空串表示本事件内部边，否则为跨事件边（指向目标事件活动版本的 toTaskId）。
 * 边语义：to 依赖 from，from 完成后 to 才可启动。
 */
public record PlanEdge(long id, long versionId, String fromTaskId, String toIncidentKey,
                       String toTaskId, Instant createdAt) {

    /** 内部边的 toIncidentKey 哨兵值（空串），保证唯一约束对内部边同样生效。 */
    public static final String INTERNAL = "";

    /**
     * 边身份：from + 目标事件 + to，三方合并按它对齐。
     */
    public String identity() {
        return fromTaskId + "->" + toIncidentKey + ":" + toTaskId;
    }

    /**
     * 同身份判断。
     */
    public boolean sameIdentity(PlanEdge other) {
        return other != null && fromTaskId.equals(other.fromTaskId)
                && toIncidentKey.equals(other.toIncidentKey) && toTaskId.equals(other.toTaskId);
    }
}

package com.example.starter.incident.plan;

import java.time.Instant;

/**
 * 方案任务运行时执行状态：跟随事件当前活动版本，按稳定 taskId 延续。
 * 发布新版本时 PENDING 行同步计划负责人，IN_PROGRESS/COMPLETED 行的事实不可回退；
 * 被移除任务的行随发布删除（COMPLETED/IN_PROGRESS 任务受合并校验保护不可移除）。
 */
public record PlanTaskState(long id, long incidentId, String taskId, PlanTaskStatus status,
                            String assignee, String startedBy, Instant startedAt,
                            String completedBy, Instant completedAt,
                            Instant createdAt, Instant updatedAt) {
}

package com.example.starter.incident.plan;

import java.time.Instant;

/**
 * 合并证据行（冻结，不可变）：三方差异、全部冲突解决、最终任务集与边集、
 * 首次响应快照均落本表。mergeKey 全局唯一；requestId 全局唯一，
 * 同参重放返回 responseJson 快照，异参 409；失败事务回滚不占键。
 */
public record PlanMerge(long id, long incidentId, String mergeKey, String requestId,
                        String requestHash, int baseVersionNo, int leftVersionNo,
                        int rightVersionNo, int resultVersionNo, String diffJson,
                        String resolutionsJson, String tasksJson, String edgesJson,
                        String responseJson, String createdBy, Instant createdAt) {
}

